    ex.pgm_profile = &td_resolver; ex.flags = XLAT12_EXTRA_TABLE_DESC; ex.ib_va = TD_IBVA; ex.desc_read = &ai_e2e_read; ex.desc_tiled_ok = &td_tiled;
    ex.desc_ctx = &g_sa;   /* an address the callback must be handed back */
    g_td.mode_ok = 0u;   /* no ask proves anything */
